"""REGEN-GENERATED-1: generated data is regenerated by a bot after merge, so pull requests stop racing each other to refresh it.

PR checks still fail on real drift (the guards are unchanged). After a merge to main this script runs every generator; the workflow commits
the result when anything changed. Every generator is a command whose failure fails the run; nothing is swallowed.

  python3 scripts/regen_generated.py            run all generators in place
  python3 scripts/regen_generated.py --list     print the generators
"""
from __future__ import annotations
import os, subprocess, sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
GENERATORS = [
    (["python3", "-c", "from foundation import writeback; print(writeback.fold())"], "."),  # WRITEBACK-SHARD-1
    (["python3", "-m", "foundation", "claims", "--fix", "--apply"], "."),
    (["python3", "scripts/build_dashboard.py"], "."),
    (["python3", "-m", "foundation", "selfmodel", "--apply"], "."),
    (["python3", "-m", "foundation", "trajectory", "--run", "--apply"], "."),  # TRAJECTORY-1: its page data reads git history, so every merge makes it stale until regenerated
    (["python3", "-m", "foundation", "ultrastability", "--data", "--apply"], "."),
    (["python3", "-m", "foundation", "decisions", "--settle", "--apply"], "."),
    (["python3", "-m", "foundation", "decisions", "--page", "--apply"], "."),
    (["python3", "-m", "foundation", "research", "--refresh-prs-if-stale"], "."),  # REDTEAM-1: the papers' merge-time source refreshes at most daily
    (["python3", "-m", "foundation", "research", "--page", "--apply"], "."),  # RESEARCH-1: white papers from the ledgers this merge changed
    (["python3", "-m", "foundation", "thought", "--run", "--apply"], "."),  # THOUGHT-1: second route (besides social-post) that schedules the next paper piece; cadence-guarded, so most runs add nothing
    (["python3", "-m", "foundation", "rescore", "--run", "--apply"], "."),  # RESCORE-1: held-out graders re-score what settle just scored
    (["python3", "-m", "foundation", "executor", "--fold", "--apply"], "."),  # PR-OUTCOME-1: what became of each pull request the executor opened
    (["python3", "-m", "foundation", "owndb", "--write"], "."),  # OWN-DB-1
    (["python3", "-m", "foundation", "tenantcontrols", "--write"], "."),  # TENANT-CONTROLS-1
    (["python3", "-m", "foundation", "upstream", "contract", "--apply"], "."),
    (["python3", "-m", "foundation", "triggers", "--sync"], "."),
    (["python3", "-m", "plugins", "self", "--write"], "seed"),
]
# Files the generators write; the workflow ignores pushes that touch only these, so the bot's own commit cannot retrigger it.
OUTPUTS = ["doctrine/decision-ledger.json", "ops/provenance.jsonl", "README.md", "platform/adapters/README.md", "site/claims-data.js", "site/dashboard-data.js", "site/self-data.js", "site/trajectory-data.js", "ops/trajectory.json", "ops/trajectory.jsonl",
           "site/ultrastability-data.js", "site/decisions-data.js", "site/research-data.js", "research/papers/chen-stratton-2026.md", "research/papers/ashby-1952.md", "research/papers/open-loops-2026.md", "research/papers/safety-by-limits-2026.md", "social/calendar.json", "ops/research/prs.json", "ops/thought/log.jsonl", "ops/decisions/outcomes.jsonl", "ops/decisions/rescore.jsonl", "ops/executor-log.jsonl", "instances/ultrastable/own-database.json", "docs/security/multi-tenant-controls.json", "core-contract.json", "doctrine/triggers.json", "seed/self/SELF.md", "seed/self/self.json"]


def run_all(root: Path = ROOT) -> list[str]:
    failed = []
    for cmd, cwd in GENERATORS:
        r = subprocess.run(cmd, cwd=root / cwd, capture_output=True, text=True)
        if r.returncode:
            failed.append(f"{' '.join(cmd)}: {(r.stderr or r.stdout).strip()[-300:]}")
    return failed


def main(argv=None) -> int:
    if "--list" in (argv or sys.argv[1:]):
        print("\n".join(" ".join(c) for c, _ in GENERATORS)); return 0
    # MARKER-ROOT-1: conflict markers that reached main are flattened before the generators run, so no PR inherits a conflict from main itself.
    m = subprocess.run([sys.executable, os.path.join(os.path.dirname(os.path.abspath(__file__)), "no_markers.py"), "--fix"], capture_output=True, text=True)
    if m.stdout.strip(): print(m.stdout.strip())
    bad = run_all()
    print("\n".join(bad) if bad else f"regenerated with {len(GENERATORS)} generators")
    return 1 if bad else 0


if __name__ == "__main__":
    sys.exit(main())
